args.CommandLine:
$logPath = "C:\Users\Mass\.gemini\antigravity\brain\d15dbe55-ca9c-4167-aa52-46a406196be9\.system_generated\logs\transcript_full.jsonl"
$diffOutput = ""

Get-Content -Path $logPath | ForEach-Object {
    if ($_ -match "multi_replace_file_content" -and $_ -match "The following changes were made by the multi_replace_file_content tool to:") {
        try {
            $json = $_ | ConvertFrom-Json
            if ($null -ne $json.content -and $json.content -match "multi_replace_file_content") {
                # In tool response
            }
            # The tool response is usually type "TOOL_RESPONSE"
            if ($json.type -eq "TOOL_RESPONSE" -and $json.content -match "diff_block_start") {
                if ($json.content.Length -gt $diffOutput.Length) {
                    $diffOutput = $json.content
                }
            }
        } catch {}
    }
}
Write-Output "Max diff length: $($diffOutput.Length)"
if ($diffOutput.Length -gt 1000) {
    Set-Content -Path "deleted_diff.txt" -Value $diffOutput -Encoding UTF8
}
